.ds-button{display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 44px;
  padding: 10px 17px;
  border-radius: 8px;
  border: 1px solid transparent;
  font-size: 14px;
  font-weight: 700;
  line-height: 1.2;
  text-decoration: none;
  transition: background-color .18s ease, transform .18s ease, border-color .18s ease;} .ds-button:not(:disabled):active{transform: translateY(1px);} .ds-button{min-height: 36px; padding: 8px 13px; font-size: 13px; font-weight: 650;} .ds-button{font-family:"Segoe UI Variable", "Segoe UI", Arial, sans-serif;cursor:default} .ds-button:focus-visible{outline:3px solid var(--focus,#a64a34);outline-offset:3px} .ds-button:disabled{opacity:.58} .ds-button-primary{background: var(--accent); color: var(--button-ink);} .ds-button-primary:not(:disabled):hover{background: var(--accent-hover);}

